/** MAIN-world hook only — no extension APIs (used via chrome.scripting.executeScript). */
export const installMainPostMessageBridge = (): void => {
  const PM_EVENT = "mv3-recorder-postmessage";
  const BRIDGE_FLAG = "__MV3_RECORDER_PM_BRIDGE__";
  const globalWindow = window as unknown as {
    postMessage: (message: unknown, targetOrigin: string, transfer?: Transferable[]) => void;
    [BRIDGE_FLAG]?: boolean;
  };

  if (globalWindow[BRIDGE_FLAG]) {
    return;
  }

  globalWindow[BRIDGE_FLAG] = true;
  const original = globalWindow.postMessage.bind(window);

  globalWindow.postMessage = (message: unknown, targetOrigin: string, transfer?: Transferable[]): void => {
    document.dispatchEvent(
      new CustomEvent(PM_EVENT, {
        detail: {
          message,
          targetOrigin: typeof targetOrigin === "string" ? targetOrigin : "*"
        }
      })
    );

    original(message, targetOrigin, transfer);
  };
};
