import type { FlowStep, PostCondition } from "./schema";
import { getStepFrameUrl, getStepTopUrl } from "./step-scope";
import { urlsMatchForReplay } from "./url";
import { POPUP_CONTAINER_SELECTORS } from "./step-inference";

const delay = (durationMs: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, durationMs));

const toConditionList = (conditions: PostCondition | PostCondition[] | undefined): PostCondition[] => {
  if (!conditions) {
    return [];
  }

  return Array.isArray(conditions) ? conditions : [conditions];
};

export const waitForTopUrl = async (
  tabId: number,
  expectedUrl: string,
  timeoutMs: number,
  readTabUrl: (tabId: number) => Promise<string | undefined>
): Promise<void> => {
  const deadline = Date.now() + timeoutMs;

  while (Date.now() < deadline) {
    const current = await readTabUrl(tabId);
    if (current && urlsMatchForReplay(current, expectedUrl)) {
      return;
    }

    await delay(200);
  }

  throw new Error(`等待顶层路由超时：${expectedUrl}`);
};

export const waitForFrameUrl = async (
  tabId: number,
  expectedUrl: string,
  timeoutMs: number,
  readFrames: (tabId: number) => Promise<Array<{ frameId?: number; url?: string }> | undefined>
): Promise<void> => {
  const deadline = Date.now() + timeoutMs;

  while (Date.now() < deadline) {
    const frames = await readFrames(tabId);
    if (frames?.some((frame) => frame.url && urlsMatchForReplay(frame.url, expectedUrl))) {
      return;
    }

    await delay(200);
  }

  throw new Error(`等待 iframe 加载超时：${expectedUrl}`);
};

export const waitForSelectorInFrame = async (
  tabId: number,
  frameId: number,
  selector: string,
  timeoutMs: number,
  runInFrame: (tabId: number, frameId: number, selector: string, timeoutMs: number) => Promise<boolean>
): Promise<void> => {
  const found = await runInFrame(tabId, frameId, selector, timeoutMs);
  if (!found) {
    throw new Error(`等待元素超时：${selector}`);
  }
};

export const waitForPopupInFrame = async (
  tabId: number,
  frameId: number,
  timeoutMs: number,
  runPopupCheck: (tabId: number, frameId: number, selectors: string, timeoutMs: number) => Promise<boolean>
): Promise<void> => {
  const found = await runPopupCheck(tabId, frameId, POPUP_CONTAINER_SELECTORS, timeoutMs);
  if (!found) {
    throw new Error("等待弹层出现超时。");
  }
};

export interface PostConditionRuntime {
  readTabUrl: (tabId: number) => Promise<string | undefined>;
  readFrames: (tabId: number) => Promise<Array<{ frameId?: number; url?: string }> | undefined>;
  runSelectorCheck: (tabId: number, frameId: number, selector: string, timeoutMs: number) => Promise<boolean>;
  runPopupCheck: (tabId: number, frameId: number, selectors: string, timeoutMs: number) => Promise<boolean>;
}

export const fulfillPostConditions = async (
  tabId: number,
  frameId: number,
  conditions: PostCondition | PostCondition[] | undefined,
  runtime: PostConditionRuntime
): Promise<void> => {
  for (const condition of toConditionList(conditions)) {
    const timeoutMs = condition.timeoutMs ?? 8_000;

    if (condition.type === "delay") {
      await delay(timeoutMs);
      continue;
    }

    if (condition.type === "topUrl" && condition.value) {
      await waitForTopUrl(tabId, condition.value, timeoutMs, runtime.readTabUrl);
      continue;
    }

    if (condition.type === "frameUrl" && condition.value) {
      await waitForFrameUrl(tabId, condition.value, timeoutMs, runtime.readFrames);
      continue;
    }

    if (condition.type === "selector" && condition.value) {
      await waitForSelectorInFrame(tabId, frameId, condition.value, timeoutMs, runtime.runSelectorCheck);
      continue;
    }

    if (condition.type === "popup") {
      await waitForPopupInFrame(tabId, frameId, timeoutMs, runtime.runPopupCheck);
    }
  }
};

/** Default wait after navigation-like clicks when the next step exposes a new top URL. */
export const inferPostConditionFromNextStep = (
  step: FlowStep,
  nextStep: FlowStep | undefined
): PostCondition | PostCondition[] | undefined => {
  if (step.postCondition || !nextStep) {
    return step.postCondition;
  }

  const sameTab = (step.tabId ?? 0) === (nextStep.tabId ?? 0);
  const nextTop = getStepTopUrl(nextStep);
  const currentTop = getStepTopUrl(step);

  if (sameTab && nextTop && currentTop && !urlsMatchForReplay(currentTop, nextTop)) {
    return { type: "topUrl", value: nextTop, timeoutMs: 12_000 };
  }

  if (nextStep.isTopFrame === false) {
    const frameUrl = getStepFrameUrl(nextStep);
    if (frameUrl) {
      return { type: "frameUrl", value: frameUrl, timeoutMs: 10_000 };
    }
  }

  return undefined;
};
