import type {
  ContentStartRequest,
  FlowStep,
  OffscreenStartRequest,
  RecorderSession,
  RecorderStateResponse,
  RuntimeMessage
} from "../shared/schema";
import { appendRecordingHistory, loadRecordingHistory, sessionToHistoryEntry } from "../shared/history";
import { makeSessionId } from "../shared/messages";
import {
  deleteSessionSnapshots,
  pruneSessionScreenshots,
  remapSessionHtml,
  remapSessionScreenshots,
  saveSessionHtml,
  saveSessionScreenshot
} from "../shared/screenshot-db";
import { getHtmlRelativePath } from "../shared/html-path";
import { getScreenshotRelativePath } from "../shared/screenshot-path";
import { fulfillPostConditions, inferPostConditionFromNextStep, type PostConditionRuntime } from "../shared/post-condition";
import { enrichAllSteps, enrichStepsBeforePush } from "../shared/step-inference";
import { getStepFrameUrl, getStepTopUrl, normalizeStepScope } from "../shared/step-scope";
import { urlsMatchForReplay } from "../shared/url";
import { installMainPostMessageBridge } from "../shared/postmessage-main";

type OffscreenApi = {
  hasDocument?: () => Promise<boolean>;
  createDocument: (options: { url: string; reasons: string[]; justification: string }) => Promise<void>;
  closeDocument?: () => Promise<void>;
};

let session: RecorderSession | undefined;
let videoUrl: string | undefined;
let captureSensitiveValues = false;
let recordPostMessages = false;
const tabsPendingRecorder = new Set<number>();
let isReplaying = false;
let replayStartUrl: string | undefined;
let ignoreNextReplayCreatedTab = false;
const replayOpenedTabs: number[] = [];

const offscreenApi = chrome.offscreen as unknown as OffscreenApi;
const replayDelayMs = 800;
const replayStepRetries = 5;
const replayOpenedTabPollMs = 4000;
const replayTabIdMap = new Map<number, number>();
let screenshotQueue: Promise<void> = Promise.resolve();
const storedSessionKey = "mv3Recorder.lastSession";
const storedVideoUrlKey = "mv3Recorder.lastVideoUrl";
const nonTextInputTypes = new Set([
  "button",
  "checkbox",
  "color",
  "file",
  "hidden",
  "image",
  "radio",
  "range",
  "reset",
  "submit"
]);

const delay = (durationMs: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, durationMs));

const persistSession = async (): Promise<void> => {
  if (!session) {
    return;
  }

  await chrome.storage.local.set({
    [storedSessionKey]: session,
    [storedVideoUrlKey]: videoUrl
  });
};

const clearPersistedSession = async (): Promise<void> => {
  const stored = await chrome.storage.local.get([storedSessionKey]);
  const storedSession = stored[storedSessionKey] as RecorderSession | undefined;

  if (storedSession?.id) {
    await deleteSessionSnapshots(storedSession.id);
  }

  await chrome.storage.local.remove([storedSessionKey, storedVideoUrlKey]);
};

const loadPersistedSession = async (): Promise<void> => {
  if (session) {
    return;
  }

  const stored = await chrome.storage.local.get([storedSessionKey, storedVideoUrlKey]);
  const storedSession = stored[storedSessionKey] as RecorderSession | undefined;

  if (!storedSession) {
    return;
  }

  session = storedSession;
  videoUrl = stored[storedVideoUrlKey] as string | undefined;
};

const getStepScopeKey = (step: FlowStep): string => `${step.tabId ?? 0}:${step.frameId ?? 0}`;

const getTargetKey = (step: FlowStep): string => {
  const target = step.target;
  const scope = getStepScopeKey(step);

  if (!target) {
    return `${scope}:${step.type}:${step.url}`;
  }

  return `${scope}:${target.attributes.id || target.attributes.name || target.selector || target.xpath}`;
};

const isRecordedTab = (tabId: number): boolean => Boolean(session?.recordedTabIds.includes(tabId));

const addRecordedTab = (tabId: number): void => {
  if (!session || isRecordedTab(tabId)) {
    return;
  }

  session = {
    ...session,
    recordedTabIds: [...session.recordedTabIds, tabId]
  };
};

const getContentStartMessage = (): ContentStartRequest | undefined => {
  if (!session) {
    return undefined;
  }

  return {
    type: "CONTENT_START",
    sessionId: session.id,
    startedAt: session.startedAt,
    captureSensitiveValues,
    recordPostMessages
  };
};

const installPostMessageHooksOnTab = async (tabId: number): Promise<void> => {
  if (!recordPostMessages) {
    return;
  }

  try {
    await chrome.scripting.executeScript({
      target: { tabId, allFrames: true },
      world: "MAIN",
      func: installMainPostMessageBridge
    });
  } catch {
    // Restricted frames are skipped by the browser.
  }
};

const getFrameIds = async (tabId: number): Promise<number[]> => {
  try {
    const frames = await chrome.webNavigation.getAllFrames({ tabId });
    if (frames?.length) {
      return frames.map((frame) => frame.frameId).filter((frameId): frameId is number => frameId !== undefined);
    }
  } catch {
    // Fall back to top frame only.
  }

  return [0];
};

const sendMessageToFrame = async (tabId: number, frameId: number, message: RuntimeMessage): Promise<void> => {
  try {
    await chrome.tabs.sendMessage(tabId, message, { frameId });
  } catch {
    await chrome.scripting.executeScript({
      target: { tabId, frameIds: [frameId] },
      files: ["content/recorder.js"]
    });
    await chrome.tabs.sendMessage(tabId, message, { frameId });
  }
};

const broadcastRecorderMessage = async (tabId: number, message: RuntimeMessage): Promise<void> => {
  const frameIds = await getFrameIds(tabId);

  for (const frameId of frameIds) {
    try {
      await sendMessageToFrame(tabId, frameId, message);
    } catch {
      // Restricted frames such as cross-origin iframes cannot be injected.
    }
  }
};

const startRecorderOnTab = async (tabId: number): Promise<void> => {
  const startMessage = getContentStartMessage();
  if (!startMessage) {
    return;
  }

  await broadcastRecorderMessage(tabId, startMessage);
};

const startRecorderOnFrame = async (tabId: number, frameId: number): Promise<void> => {
  const startMessage = getContentStartMessage();
  if (!startMessage) {
    return;
  }

  try {
    await sendMessageToFrame(tabId, frameId, startMessage);
  } catch {
    // Ignore frames that cannot be reached.
  }
};

const isTextEntryStep = (step: FlowStep): boolean => {
  const tagName = step.target?.tagName.toLowerCase();

  if (tagName === "textarea" || tagName === "select") {
    return true;
  }

  if (tagName !== "input") {
    return false;
  }

  const inputType = step.target?.attributes.type?.toLowerCase() ?? "text";
  return !nonTextInputTypes.has(inputType);
};

const shouldMergeAsTextEntry = (previousStep: FlowStep, nextStep: FlowStep): boolean => {
  if (!isTextEntryStep(nextStep) || !["input", "change"].includes(nextStep.type)) {
    return false;
  }

  return getTargetKey(previousStep) === getTargetKey(nextStep) && ["click", "input", "change"].includes(previousStep.type);
};

const isSelectLikeStep = (step: FlowStep): boolean => {
  const tagName = step.target?.tagName.toLowerCase();

  if (tagName === "select") {
    return true;
  }

  if (tagName === "input") {
    const role = step.target?.attributes.role;
    const className = step.target?.attributes.class ?? "";
    return role === "combobox" || className.includes("el-select") || className.includes("ant-select");
  }

  return false;
};

/** Only collapse same-target clicks that arrive almost together (duplicate recording), not double-clicks. */
const ACCIDENTAL_DUPLICATE_CLICK_MS = 80;

const areEquivalentInteractionSteps = (previousStep: FlowStep, nextStep: FlowStep): boolean => {
  if (getTargetKey(previousStep) !== getTargetKey(nextStep)) {
    return false;
  }

  if (previousStep.value !== nextStep.value) {
    return false;
  }

  const interactionTypes = new Set<FlowStep["type"]>(["click", "input", "change"]);
  if (!interactionTypes.has(previousStep.type) || !interactionTypes.has(nextStep.type)) {
    return false;
  }

  if (previousStep.type === "click" && nextStep.type === "click") {
    const gapMs = nextStep.timestampMs - previousStep.timestampMs;
    return gapMs >= 0 && gapMs < ACCIDENTAL_DUPLICATE_CLICK_MS;
  }

  return true;
};

const mergeTextEntryStep = (previousStep: FlowStep, nextStep: FlowStep): FlowStep | undefined => {
  if (!shouldMergeAsTextEntry(previousStep, nextStep)) {
    return undefined;
  }

  if (
    (previousStep.type === "input" || previousStep.type === "change") &&
    (nextStep.type === "input" || nextStep.type === "change") &&
    previousStep.value === nextStep.value
  ) {
    return {
      ...nextStep,
      type: isSelectLikeStep(nextStep) ? "change" : "input",
      id: previousStep.id,
      timestampMs: nextStep.timestampMs
    };
  }

  return {
    ...nextStep,
    type: isSelectLikeStep(nextStep) ? "change" : "input",
    id: previousStep.type === "click" ? previousStep.id : nextStep.id,
    timestampMs: previousStep.type === "click" ? previousStep.timestampMs : nextStep.timestampMs
  };
};

const getActiveTab = async (): Promise<chrome.tabs.Tab> => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });

  if (!tab?.id || !tab.url) {
    throw new Error("未找到可录制的当前标签页。");
  }

  if (/^(chrome|edge|about|chrome-extension):\/\//.test(tab.url)) {
    throw new Error("浏览器内置页面无法注入内容脚本，请切换到普通网页。");
  }

  return tab;
};

const getTabMediaStreamId = (tabId: number): Promise<string> =>
  new Promise((resolve, reject) => {
    chrome.tabCapture.getMediaStreamId({ targetTabId: tabId }, (streamId) => {
      const error = chrome.runtime.lastError;

      if (error || !streamId) {
        reject(new Error(error?.message ?? "无法获取当前 Tab 的录制流。"));
        return;
      }

      resolve(streamId);
    });
  });

const ensureOffscreenDocument = async (): Promise<void> => {
  const hasDocument = offscreenApi.hasDocument ? await offscreenApi.hasDocument() : false;

  if (hasDocument) {
    return;
  }

  await offscreenApi.createDocument({
    url: "offscreen.html",
    reasons: ["USER_MEDIA"],
    justification: "Record the active tab with MediaRecorder while the MV3 service worker can suspend."
  });
};

const stopRecorderOnAllTabs = async (): Promise<void> => {
  if (!session) {
    return;
  }

  const stopMessage: RuntimeMessage = { type: "CONTENT_STOP" };

  for (const tabId of session.recordedTabIds) {
    try {
      await broadcastRecorderMessage(tabId, stopMessage);
    } catch {
      // Tab may already be closed.
    }
  }
};

const waitForTabComplete = async (tabId: number): Promise<void> => {
  const tab = await chrome.tabs.get(tabId);

  if (tab.status === "complete") {
    return;
  }

  await new Promise<void>((resolve) => {
    const listener = (updatedTabId: number, changeInfo: chrome.tabs.TabChangeInfo): void => {
      if (updatedTabId === tabId && changeInfo.status === "complete") {
        chrome.tabs.onUpdated.removeListener(listener);
        resolve();
      }
    };

    chrome.tabs.onUpdated.addListener(listener);
    setTimeout(() => {
      chrome.tabs.onUpdated.removeListener(listener);
      resolve();
    }, 10000);
  });
};

const navigateTab = async (tabId: number, url: string): Promise<void> => {
  await chrome.tabs.update(tabId, { url });
  await waitForTabComplete(tabId);
};

const shouldNavigateToStepUrl = (currentUrl: string | undefined, stepUrl: string): boolean => {
  if (!currentUrl) {
    return true;
  }

  return !urlsMatchForReplay(currentUrl, stepUrl);
};

const getStepNavigationUrl = (step: FlowStep): string | undefined => {
  if (step.type === "navigate") {
    return step.navigateUrl ?? getStepTopUrl(step);
  }

  return getStepTopUrl(step);
};

const renumberSteps = (steps: FlowStep[], sessionId: string): FlowStep[] =>
  steps.map((step, index) => ({
    ...step,
    id: `${sessionId}-step-${index + 1}`
  }));

const postConditionRuntime: PostConditionRuntime = {
  readTabUrl: async (tabId: number) => (await chrome.tabs.get(tabId)).url,
  readFrames: async (tabId: number) => {
    const frames = await chrome.webNavigation.getAllFrames({ tabId });
    return frames ?? undefined;
  },
  runSelectorCheck: async (tabId, frameId, selector, timeoutMs) => {
    const results = await chrome.scripting.executeScript({
      target: { tabId, frameIds: [frameId] },
      func: (sel: string, timeout: number) =>
        new Promise<boolean>((resolve) => {
          const deadline = Date.now() + timeout;
          const tick = (): void => {
            try {
              const element = document.querySelector(sel);
              if (element instanceof HTMLElement && element.offsetParent !== null) {
                resolve(true);
                return;
              }
            } catch {
              // Invalid selector — keep polling until timeout.
            }

            if (Date.now() >= deadline) {
              resolve(false);
              return;
            }

            window.setTimeout(tick, 200);
          };
          tick();
        }),
      args: [selector, timeoutMs]
    });

    return Boolean(results[0]?.result);
  },
  runPopupCheck: async (tabId, frameId, selectors, timeoutMs) => {
    const results = await chrome.scripting.executeScript({
      target: { tabId, frameIds: [frameId] },
      func: (selectorList: string, timeout: number) =>
        new Promise<boolean>((resolve) => {
          const candidates = selectorList.split(",").map((item) => item.trim()).filter(Boolean);
          const deadline = Date.now() + timeout;
          const tick = (): void => {
            for (const sel of candidates) {
              try {
                const element = document.querySelector(sel);
                if (element instanceof HTMLElement && element.offsetParent !== null) {
                  resolve(true);
                  return;
                }
              } catch {
                continue;
              }
            }

            if (Date.now() >= deadline) {
              resolve(false);
              return;
            }

            window.setTimeout(tick, 200);
          };
          tick();
        }),
      args: [selectors, timeoutMs]
    });

    return Boolean(results[0]?.result);
  }
};

const replayPostMessageStep = async (tabId: number, step: FlowStep): Promise<void> => {
  const payload = step.postMessage;
  if (!payload) {
    return;
  }

  await chrome.scripting.executeScript({
    target: { tabId, allFrames: true },
    world: "MAIN",
    func: (data: unknown, targetOrigin: string) => {
      window.postMessage(data, targetOrigin);
    },
    args: [payload.data, payload.targetOrigin ?? "*"]
  });
};

const waitForTopUrlAfterInteraction = async (
  tabId: number,
  step: FlowStep,
  nextStep: FlowStep | undefined
): Promise<void> => {
  const conditions = step.postCondition ?? inferPostConditionFromNextStep(step, nextStep);
  if (!conditions) {
    return;
  }

  await fulfillPostConditions(tabId, 0, conditions, postConditionRuntime);
};

const extractSessionIdFromSteps = (steps: FlowStep[]): string | undefined => {
  const firstId = steps[0]?.id;
  if (!firstId) {
    return undefined;
  }

  const match = firstId.match(/^(.*)-step-\d+$/);
  return match?.[1];
};

const prepareReplaySteps = (steps: FlowStep[], sessionId?: string): FlowStep[] => {
  const resolvedSessionId = sessionId ?? extractSessionIdFromSteps(steps) ?? "session";

  return enrichAllSteps(resolvedSessionId, steps)
    .map(normalizeStepScope)
    .filter((step, index, allSteps) => !shouldSkipReplayStep(step, index, allSteps));
};

const shouldSkipReplayStep = (step: FlowStep, index: number, steps: FlowStep[]): boolean => {
  if (step.type !== "click" || step.value) {
    return false;
  }

  const tagName = step.target?.tagName.toLowerCase();
  if (tagName !== "input" && tagName !== "textarea") {
    return false;
  }

  const nextStep = steps[index + 1];
  if (!nextStep || !["input", "change"].includes(nextStep.type)) {
    return false;
  }

  return getTargetKey(step) === getTargetKey(nextStep);
};

const resolveFrameIdForStep = async (tabId: number, step: FlowStep): Promise<number> => {
  const frameUrl = getStepFrameUrl(step);

  if (!frameUrl || (step.frameId ?? 0) === 0) {
    return step.frameId ?? 0;
  }

  try {
    const frames = await chrome.webNavigation.getAllFrames({ tabId });
    const matchedFrame = frames?.find((frame) => frame.url && urlsMatchForReplay(frame.url, frameUrl));
    if (matchedFrame?.frameId !== undefined) {
      return matchedFrame.frameId;
    }
  } catch {
    // Fall back to the recorded frame id.
  }

  return step.frameId ?? 0;
};

const tabExists = async (tabId: number): Promise<boolean> => {
  try {
    await chrome.tabs.get(tabId);
    return true;
  } catch {
    return false;
  }
};

const findFirstStepForRecordedTab = (steps: FlowStep[], recordedTabId: number, recordedRootTabId: number): FlowStep | undefined =>
  steps.find((step) => (step.tabId ?? recordedRootTabId) === recordedTabId);

const openReplayTabForRecordedId = async (
  recordedTabId: number,
  steps: FlowStep[],
  recordedRootTabId: number,
  active: boolean,
  preferredUrl?: string
): Promise<number> => {
  const firstStep = findFirstStepForRecordedTab(steps, recordedTabId, recordedRootTabId);
  const openUrl =
    preferredUrl ??
    ((firstStep ? getStepNavigationUrl(firstStep) : undefined) || (replayStartUrl ?? session?.startUrl));

  if (!openUrl) {
    throw new Error(`无法为标签页 ${recordedTabId} 确定打开地址。`);
  }

  ignoreNextReplayCreatedTab = true;
  const createdTab = await chrome.tabs.create({ url: openUrl, active });
  if (!createdTab.id) {
    throw new Error("无法打开回放页面。");
  }

  replayTabIdMap.set(recordedTabId, createdTab.id);
  await waitForTabComplete(createdTab.id);
  await delay(1000);
  return createdTab.id;
};

const waitForReplayOpenedTab = async (): Promise<number | undefined> => {
  const deadline = Date.now() + replayOpenedTabPollMs;

  while (Date.now() < deadline) {
    const openedTabId = replayOpenedTabs.shift();
    if (openedTabId !== undefined && (await tabExists(openedTabId))) {
      return openedTabId;
    }

    await delay(250);
  }

  return undefined;
};

const resolveReplayTabId = async (
  recordedTabId: number,
  step: FlowStep,
  fallbackTabId: number,
  recordedRootTabId: number,
  steps: FlowStep[]
): Promise<number> => {
  const mappedTabId = replayTabIdMap.get(recordedTabId);
  if (mappedTabId !== undefined && (await tabExists(mappedTabId))) {
    return mappedTabId;
  }

  if (await tabExists(recordedTabId)) {
    replayTabIdMap.set(recordedTabId, recordedTabId);
    return recordedTabId;
  }

  if (recordedTabId !== recordedRootTabId) {
    const openedTabId = await waitForReplayOpenedTab();
    if (openedTabId !== undefined) {
      replayTabIdMap.set(recordedTabId, openedTabId);
      await waitForTabComplete(openedTabId);
      await delay(800);
      return openedTabId;
    }

    return openReplayTabForRecordedId(
      recordedTabId,
      steps,
      recordedRootTabId,
      true,
      getStepNavigationUrl(step)
    );
  }

  const openUrl = getStepNavigationUrl(step) || (replayStartUrl ?? session?.startUrl);
  if (!openUrl) {
    return fallbackTabId;
  }

  return openReplayTabForRecordedId(recordedTabId, steps, recordedRootTabId, true, openUrl);
};

const runReplayStepOnFrame = async (
  tabId: number,
  frameId: number,
  step: FlowStep
): Promise<{ ok: boolean; error?: string }> => {
  await ensureReplayScriptInFrame(tabId, frameId);

  try {
    const results = await chrome.scripting.executeScript({
      target: { tabId, frameIds: [frameId] },
      func: async (stepArg: FlowStep) => {
        const runner = window.__mv3ExecuteReplayStep;
        if (typeof runner !== "function") {
          return { ok: false as const, error: "回放脚本未加载，请刷新页面后重试。" };
        }

        return runner(stepArg);
      },
      args: [step]
    });

    const result = results[0]?.result as { ok: boolean; error?: string } | undefined;
    if (result?.ok) {
      return { ok: true };
    }

    return { ok: false, error: result?.error ?? "回放未返回结果。" };
  } catch (error: unknown) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
};

const stepMayCauseNavigation = (step: FlowStep): boolean =>
  step.type === "click" || step.type === "submit" || step.type === "navigate";

const replayStepWithRetry = async (tabId: number, step: FlowStep, frameId: number): Promise<void> => {
  let lastError: Error | undefined;

  for (let attempt = 0; attempt < replayStepRetries; attempt++) {
    const response = await runReplayStepOnFrame(tabId, frameId, step);

    if (response.ok) {
      if (stepMayCauseNavigation(step)) {
        await waitForTabComplete(tabId);
        await delay(600);
      }
      return;
    }

    const errorText = response.error ?? "";
    const shouldRetry =
      errorText.includes("message port closed") ||
      errorText.includes("Receiving end does not exist") ||
      errorText.includes("Could not establish connection") ||
      errorText.includes("回放脚本未加载") ||
      errorText.includes("找不到元素");

    lastError = new Error(errorText || `流程回放失败：${step.id}`);

    if (!shouldRetry) {
      throw lastError;
    }

    await waitForTabComplete(tabId);
    await delay(800);
    await ensureReplayScriptAllFrames(tabId);
    await delay(400);
  }

  throw lastError ?? new Error(`流程回放失败：${step.id}`);
};

const isReplayScriptReadyInFrame = async (tabId: number, frameId: number): Promise<boolean> => {
  try {
    const results = await chrome.scripting.executeScript({
      target: { tabId, frameIds: [frameId] },
      func: () => typeof window.__mv3ExecuteReplayStep === "function"
    });
    return Boolean(results[0]?.result);
  } catch {
    return false;
  }
};

const ensureReplayScriptInFrame = async (tabId: number, frameId: number): Promise<void> => {
  if (await isReplayScriptReadyInFrame(tabId, frameId)) {
    return;
  }

  try {
    await chrome.scripting.executeScript({
      target: { tabId, frameIds: [frameId] },
      files: ["content/replay.js"]
    });
  } catch {
    if (!(await isReplayScriptReadyInFrame(tabId, frameId))) {
      await ensureReplayScriptAllFrames(tabId);
    }
  }
};

const ensureReplayScriptAllFrames = async (tabId: number): Promise<void> => {
  if (await isReplayScriptReadyInFrame(tabId, 0)) {
    return;
  }

  await chrome.scripting.executeScript({
    target: { tabId, allFrames: true },
    files: ["content/replay.js"]
  });
};

const sendOffscreenMessage = async <T>(message: RuntimeMessage): Promise<T> => {
  const response = (await chrome.runtime.sendMessage(message)) as { ok: boolean; payload?: T; error?: string };

  if (!response?.ok) {
    throw new Error(response?.error ?? "Offscreen recorder failed.");
  }

  return response.payload as T;
};

const releaseOffscreenCapture = async (): Promise<void> => {
  const hasDocument = offscreenApi.hasDocument ? await offscreenApi.hasDocument() : false;

  if (!hasDocument) {
    return;
  }

  try {
    await chrome.runtime.sendMessage({ type: "OFFSCREEN_RELEASE" });
  } catch {
    // Offscreen may already be closed.
  }
};

const startRecording = async (
  shouldCaptureSensitiveValues: boolean,
  shouldRecordPostMessages = false
): Promise<RecorderStateResponse> => {
  if (session?.status === "recording") {
    return { ok: true, session };
  }

  await clearPersistedSession();
  screenshotQueue = Promise.resolve();

  const tab = await getActiveTab();
  const startedAt = new Date().toISOString();
  const sessionId = makeSessionId();
  const tabId = tab.id as number;

  videoUrl = undefined;
  await ensureOffscreenDocument();
  await releaseOffscreenCapture();

  captureSensitiveValues = shouldCaptureSensitiveValues;
  recordPostMessages = shouldRecordPostMessages;
  tabsPendingRecorder.clear();

  session = {
    id: sessionId,
    status: "recording",
    tabId,
    recordedTabIds: [tabId],
    tabTitle: tab.title,
    startUrl: tab.url as string,
    startedAt,
    durationMs: 0,
    steps: []
  };

  try {
    await startRecorderOnTab(tabId);
    await installPostMessageHooksOnTab(tabId);

    const streamId = await getTabMediaStreamId(tabId);
    await sendOffscreenMessage<void>({ type: "OFFSCREEN_START", streamId, sessionId } satisfies OffscreenStartRequest);
  } catch (error: unknown) {
    try {
      await stopRecorderOnAllTabs();
    } catch {
      // Ignore cleanup failures.
    }

    await releaseOffscreenCapture();

    const messageText = error instanceof Error ? error.message : String(error);
    session = {
      ...session,
      status: "error",
      error: messageText
    };
    throw new Error(messageText);
  }

  return { ok: true, session };
};

const stopRecording = async (): Promise<RecorderStateResponse> => {
  if (!session) {
    return { ok: true };
  }

  if (session.status !== "recording") {
    return { ok: true, session, videoUrl };
  }

  try {
    await stopRecorderOnAllTabs();
  } catch {
    // The page may have navigated or closed; keep the captured data that is already available.
  }

  tabsPendingRecorder.clear();
  await screenshotQueue;

  const stoppedAt = new Date();
  const startedAt = new Date(session.startedAt);
  const videoPayload = await sendOffscreenMessage<{ mimeType: string; objectUrl: string; sizeBytes: number }>({
    type: "OFFSCREEN_STOP"
  });
  videoUrl = videoPayload.objectUrl;

  session = {
    ...session,
    status: "stopped",
    endedAt: stoppedAt.toISOString(),
    durationMs: Math.max(0, stoppedAt.getTime() - startedAt.getTime()),
    video: {
      mimeType: videoPayload.mimeType,
      fileName: `${session.id}.webm`,
      durationMs: Math.max(0, stoppedAt.getTime() - startedAt.getTime()),
      sizeBytes: videoPayload.sizeBytes
    },
    videoUrl
  };

  await persistSession();

  if (session.steps.length) {
    await appendRecordingHistory(sessionToHistoryEntry(session));
    const history = await loadRecordingHistory();
    await pruneSessionScreenshots(history.map((entry) => entry.id));
  }

  return { ok: true, session, videoUrl };
};

const replayFlow = async (steps: FlowStep[], contextStartUrl?: string): Promise<RecorderStateResponse> => {
  const replaySteps = prepareReplaySteps(steps, session?.id);
  const warnings: string[] = [];
  const warnedStepIds = new Set<string>();

  if (!replaySteps.length) {
    throw new Error("没有可回放的步骤。");
  }

  replayTabIdMap.clear();
  replayOpenedTabs.length = 0;
  isReplaying = true;
  replayStartUrl = contextStartUrl ?? session?.startUrl;

  const recordedRootTabId = replaySteps[0]?.tabId ?? session?.tabId ?? (await getActiveTab()).id;

  if (!recordedRootTabId) {
    throw new Error("未找到可回放的标签页。");
  }

  let activeTabId = await resolveReplayTabId(
    recordedRootTabId,
    replaySteps[0],
    recordedRootTabId,
    recordedRootTabId,
    replaySteps
  );

  const startUrl =
    replayStartUrl ??
    session?.startUrl ??
    (replaySteps[0] ? getStepTopUrl(replaySteps[0]) : undefined) ??
    getStepNavigationUrl(replaySteps[0]);
  if (startUrl) {
    const tab = await chrome.tabs.get(activeTabId);
    if (shouldNavigateToStepUrl(tab.url, startUrl)) {
      await navigateTab(activeTabId, startUrl);
    }
  }

  await ensureReplayScriptAllFrames(activeTabId);
  await delay(1200);

  let lastRecordedTabId: number | undefined;

  try {
    for (let stepIndex = 0; stepIndex < replaySteps.length; stepIndex++) {
      const step = replaySteps[stepIndex];
      const recordedTabId = step.tabId ?? recordedRootTabId;

      try {
        const targetTabId = await resolveReplayTabId(
          recordedTabId,
          step,
          activeTabId,
          recordedRootTabId,
          replaySteps
        );

        if (targetTabId !== activeTabId) {
          await chrome.tabs.update(targetTabId, { active: true });
          activeTabId = targetTabId;
          lastRecordedTabId = undefined;
          await ensureReplayScriptAllFrames(activeTabId);
          await delay(800);
        }

        const switchedTab = lastRecordedTabId !== undefined && lastRecordedTabId !== recordedTabId;
        lastRecordedTabId = recordedTabId;

        if (step.type === "navigate") {
          const navigateUrl = getStepNavigationUrl(step);
          if (navigateUrl) {
            const tab = await chrome.tabs.get(targetTabId);
            if (shouldNavigateToStepUrl(tab.url, navigateUrl)) {
              await navigateTab(targetTabId, navigateUrl);
              await ensureReplayScriptAllFrames(targetTabId);
              await delay(1000);
            }
          }

          await waitForTopUrlAfterInteraction(targetTabId, step, replaySteps[stepIndex + 1]);
          await delay(replayDelayMs);
          continue;
        }

        if (switchedTab) {
          const navigationUrl = getStepNavigationUrl(step);
          if (navigationUrl) {
            const tab = await chrome.tabs.get(targetTabId);
            if (shouldNavigateToStepUrl(tab.url, navigationUrl)) {
              await navigateTab(targetTabId, navigationUrl);
              await ensureReplayScriptAllFrames(targetTabId);
              await delay(1000);
            }
          }
        }

        if (step.type === "postmessage") {
          await replayPostMessageStep(targetTabId, step);
          await delay(replayDelayMs);
          continue;
        }

        if (step.type === "wait") {
          await delay(step.waitMs ?? 500);
          if (step.postCondition) {
            const frameId = await resolveFrameIdForStep(targetTabId, step);
            try {
              await fulfillPostConditions(targetTabId, frameId, step.postCondition, postConditionRuntime);
            } catch (postConditionError: unknown) {
              const message =
                postConditionError instanceof Error ? postConditionError.message : String(postConditionError);
              warnings.push(`步骤 ${step.id}（等待条件）：${message}`);
            }
          }
          continue;
        }

        const frameId = await resolveFrameIdForStep(targetTabId, step);
        await replayStepWithRetry(targetTabId, step, frameId);

        try {
          await waitForTopUrlAfterInteraction(targetTabId, step, replaySteps[stepIndex + 1]);
        } catch (postConditionError: unknown) {
          const message = postConditionError instanceof Error ? postConditionError.message : String(postConditionError);
          warnings.push(`步骤 ${step.id}（等待条件）：${message}`);
        }

        if (stepMayCauseNavigation(step)) {
          const openedTabId = await waitForReplayOpenedTab();
          if (openedTabId !== undefined) {
            const nextStepOnNewTab = replaySteps.slice(stepIndex + 1).find((futureStep) => {
              const futureTabId = futureStep.tabId ?? recordedRootTabId;
              return futureTabId !== recordedRootTabId && !replayTabIdMap.has(futureTabId);
            });

            if (nextStepOnNewTab) {
              const futureTabId = nextStepOnNewTab.tabId ?? recordedRootTabId;
              replayTabIdMap.set(futureTabId, openedTabId);
              await waitForTabComplete(openedTabId);
            }
          }
        }

        await delay(replayDelayMs);
        await waitForTabComplete(targetTabId);
      } catch (error: unknown) {
        if (warnedStepIds.has(step.id)) {
          continue;
        }

        warnedStepIds.add(step.id);
        const message = error instanceof Error ? error.message : String(error);
        warnings.push(`步骤 ${step.id}：${message}`);
      }
    }
  } finally {
    isReplaying = false;
    replayStartUrl = undefined;
  }

  if (warnings.length === replaySteps.length) {
    throw new Error(warnings.join("；"));
  }

  return {
    ok: true,
    session,
    videoUrl,
    replayWarnings: warnings.length ? warnings : undefined
  };
};

const getState = async (): Promise<RecorderStateResponse> => {
  await loadPersistedSession();

  if (session?.status === "recording") {
    session = {
      ...session,
      durationMs: Date.now() - new Date(session.startedAt).getTime()
    };
  }

  return { ok: true, session, videoUrl };
};

const captureTabScreenshot = async (tabId: number): Promise<string | undefined> => {
  try {
    const tab = await chrome.tabs.get(tabId);
    if (!tab.windowId) {
      return undefined;
    }

    return await chrome.tabs.captureVisibleTab(tab.windowId, { format: "png" });
  } catch {
    return undefined;
  }
};

const saveStepHtml = async (stepId: string, html: string): Promise<void> => {
  if (!session || !html) {
    return;
  }

  try {
    await saveSessionHtml(session.id, stepId, html);

    const htmlPath = getHtmlRelativePath(stepId);
    session = {
      ...session,
      steps: session.steps.map((recordedStep) =>
        recordedStep.id === stepId ? { ...recordedStep, html: htmlPath } : recordedStep
      )
    };
  } catch {
    // HTML capture failures must not interrupt recording.
  }
};

const scheduleStepScreenshot = (stepId: string, tabId: number): void => {
  screenshotQueue = screenshotQueue
    .then(async () => {
      if (!session || session.status !== "recording") {
        return;
      }

      const dataUrl = await captureTabScreenshot(tabId);
      if (!dataUrl) {
        return;
      }

      await saveSessionScreenshot(session.id, stepId, dataUrl);

      const screenshot = getScreenshotRelativePath(stepId);
      session = {
        ...session,
        steps: session.steps.map((recordedStep) =>
          recordedStep.id === stepId ? { ...recordedStep, screenshot } : recordedStep
        )
      };
    })
    .catch(() => {
      // Screenshot failures must not interrupt recording.
    });
};

const appendStep = (step: FlowStep): { stepId: string; tabId: number } | undefined => {
  if (!session || session.status !== "recording") {
    return undefined;
  }

  const stepsBeforeRenumber = [...session.steps];
  let steps = [...session.steps];
  const previousStep = steps.at(-1);
  const normalizedStep = normalizeStepScope(step);

  if (previousStep) {
    const mergedStep = mergeTextEntryStep(previousStep, normalizedStep);
    if (mergedStep) {
      steps[steps.length - 1] = mergedStep;
    } else if (areEquivalentInteractionSteps(previousStep, normalizedStep)) {
      const preferredStep =
        normalizedStep.type === "change" || (normalizedStep.value !== undefined && previousStep.value === undefined)
          ? normalizedStep
          : previousStep;
      steps[steps.length - 1] = {
        ...preferredStep,
        id: previousStep.id
      };
    } else {
      steps = enrichStepsBeforePush(session.id, steps, normalizedStep);
    }
  } else {
    steps.push(normalizedStep);
  }

  const renumberedSteps = renumberSteps(steps, session.id);
  const finalSteps = renumberedSteps.map((renumberedStep, index) => {
    const priorId = stepsBeforeRenumber[index]?.id;
    if (priorId && priorId !== renumberedStep.id) {
      const updates: Partial<FlowStep> = {};
      if (renumberedStep.screenshot) {
        updates.screenshot = getScreenshotRelativePath(renumberedStep.id);
      }
      if (renumberedStep.html) {
        updates.html = getHtmlRelativePath(renumberedStep.id);
      }
      if (Object.keys(updates).length) {
        return { ...renumberedStep, ...updates };
      }
    }

    return renumberedStep;
  });

  session = {
    ...session,
    durationMs: Date.now() - new Date(session.startedAt).getTime(),
    steps: finalSteps
  };

  void remapSessionScreenshots(session.id, stepsBeforeRenumber, finalSteps);
  void remapSessionHtml(session.id, stepsBeforeRenumber, finalSteps);

  const lastStep = finalSteps.at(-1);
  if (!lastStep) {
    return undefined;
  }

  return {
    stepId: lastStep.id,
    tabId: step.tabId ?? session.tabId
  };
};

chrome.tabs.onCreated.addListener((tab) => {
  void (async () => {
    if (isReplaying && tab.id) {
      if (ignoreNextReplayCreatedTab) {
        ignoreNextReplayCreatedTab = false;
        return;
      }

      replayOpenedTabs.push(tab.id);
      return;
    }

    if (!session || session.status !== "recording" || !tab.id) {
      return;
    }

    const openerTabId = tab.openerTabId;
    if (openerTabId === undefined || !isRecordedTab(openerTabId)) {
      return;
    }

    addRecordedTab(tab.id);
    tabsPendingRecorder.add(tab.id);
  })();
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo) => {
  void (async () => {
    if (changeInfo.status !== "complete" || !session || session.status !== "recording") {
      return;
    }

    if (!tabsPendingRecorder.has(tabId) || !isRecordedTab(tabId)) {
      return;
    }

    tabsPendingRecorder.delete(tabId);
    await startRecorderOnTab(tabId);
    await installPostMessageHooksOnTab(tabId);
  })();
});

chrome.webNavigation.onCompleted.addListener((details) => {
  void (async () => {
    if (!session || session.status !== "recording") {
      return;
    }

    if (!isRecordedTab(details.tabId) || details.frameId === undefined) {
      return;
    }

    if (details.frameId === 0) {
      return;
    }

    await startRecorderOnFrame(details.tabId, details.frameId);
  })();
});

chrome.runtime.onMessage.addListener((message: RuntimeMessage, sender, sendResponse) => {
  if (message.type === "CONTENT_STEP") {
    if (!sender.tab?.id || !isRecordedTab(sender.tab.id)) {
      sendResponse({ ok: true });
      return false;
    }

    const screenshotTarget = appendStep({
      ...message.step,
      tabId: sender.tab.id,
      topUrl: sender.tab.url,
      frameId: sender.frameId ?? 0,
      frameUrl: sender.url ?? message.step.url,
      isTopFrame: (sender.frameId ?? 0) === 0
    });

    if (screenshotTarget) {
      scheduleStepScreenshot(screenshotTarget.stepId, screenshotTarget.tabId);
      if (message.pageHtml) {
        void saveStepHtml(screenshotTarget.stepId, message.pageHtml);
      }
    }

    sendResponse({ ok: true });
    return false;
  }

  const run = async (): Promise<RecorderStateResponse> => {
    if (message.type === "START_RECORDING") {
      return startRecording(message.captureSensitiveValues, message.recordPostMessages);
    }

    if (message.type === "STOP_RECORDING") {
      return stopRecording();
    }

    if (message.type === "GET_STATE") {
      return getState();
    }

    if (message.type === "REPLAY_FLOW") {
      return replayFlow(message.steps, message.startUrl);
    }

    return { ok: false, error: "Unsupported message." };
  };

  run()
    .then((response) => sendResponse(response))
    .catch((error: unknown) => {
      const messageText = error instanceof Error ? error.message : String(error);
      if (session) {
        session = { ...session, status: "error", error: messageText };
      }
      sendResponse({ ok: false, session, error: messageText });
    });

  return true;
});
